def eur(x): return f"{x:,.2f}".replace(",", "X").replace(".", ",").replace("X", ".")

def tab_minimi():
    rows = [["Livello", "Tabellare gen-26", "Tabellare ott-26", "Tabellare mar-27", "Tabellare nov-27", "Contingenza", "EAR"]]
